// SendTestMessageTemplate is the resolver for the sendTestMessageTemplate field.
//
// A test send renders the draft on the server and mails it, which the existing
// REST test-send cannot do: that one is bound to an email profile, not to a
// template version, so it has no way to render unpublished content.
func (r *MutationResolver) SendTestMessageTemplate(ctx context.Context, input gqlmodel.SendTestMessageTemplateInput) (bool, error) {
	authCtx, err := r.RequirePermission(
		ctx, permission.ResourceDocumentTemplate, permission.OpUpdate,
	)
	if err != nil {
		return false, err
	}

	preview, err := r.PreviewFor(ctx, authCtx, &gqlmodel.DocumentTemplatePreviewInput{
		Kind:      input.Kind,
		VersionID: input.VersionID,
		Content:   input.Content,
	})
	if err != nil {
		return false, err
	}

	if preview.Diagnostics.HasErrors() {
		return false, errortypes.NewBusinessError(
			"This template does not render yet, so there is nothing to send. {0}", preview.Diagnostics.Errors().Summary(),
		)
	}

	if _, err = r.EmailService.Send(ctx, &services.SendEmailRequest{
		TenantInfo: base.TenantInfo(authCtx),
		Purpose:    email.PurposeGeneral,
		To:         []string{input.ToEmail},
		// The subject is marked so a test can never be mistaken for the real
		// notice by whoever receives it.
		Subject: "[TEST] " + preview.Subject,
		HTML:    preview.HTML,
		Text:    preview.Text,
	}); err != nil {
		return false, err
	}

	return true, nil
}

